contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), address(this), address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint16 _feeRate) public {
        require(_feeRate <= 10_000);

        bool reverted;
        c.initialize(address(1), address(2), 1, 1, 0, _feeRate, bytes32(0), false, false); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert((!reverted) == (_feeRate <= 5_000) && (!reverted == c.initialized()));
    }
}

