// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function _run(uint16 _feeRate) internal {
        _feeRate = uint16(bound(uint256(_feeRate), 0, 10000));
        bool reverted;
        try c.initialize(address(1), address(2), 1, 1, 0, _feeRate, bytes32(0), false, false) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue((!reverted) == (_feeRate <= 5_000) && (!reverted == c.initialized()));
    }

    function testFuzz_run(uint16 _feeRate) public {
        _run(_feeRate);
    }

    receive() external payable {}
}
